CREATE TYPE "AcquisitionExpiryAction" AS ENUM ('REFRESH_RESEARCH','MANUAL_VERIFICATION','NURTURE','DISQUALIFY','ARCHIVE');
CREATE TYPE "FunnelBlockerStatus" AS ENUM ('OPEN','RESOLVED','WAIVED');
ALTER TABLE "AcquisitionFunnel" ADD COLUMN "nextReviewAt" TIMESTAMP(3), ADD COLUMN "responsibleActor" TEXT, ADD COLUMN "lastActivityAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "AcquisitionStageHistory" ADD COLUMN "responsibleActor" TEXT, ADD COLUMN "approvalEvidence" JSONB, ADD COLUMN "blockerSnapshot" JSONB, ADD COLUMN "exitedAt" TIMESTAMP(3);
CREATE TABLE "AcquisitionStagePolicy" ("id" TEXT PRIMARY KEY,"stage" "AcquisitionStage" NOT NULL,"version" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,"reviewIntervalHours" INTEGER NOT NULL,"expiryAction" "AcquisitionExpiryAction" NOT NULL,"requiredGateTypes" "AcquisitionGateType"[],"highValueThresholdCents" BIGINT,"reason" TEXT NOT NULL,"effectiveAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AcquisitionStagePolicy_review_check" CHECK ("reviewIntervalHours" > 0));
CREATE UNIQUE INDEX "AcquisitionStagePolicy_stage_version_key" ON "AcquisitionStagePolicy"("stage","version");
CREATE INDEX "AcquisitionStagePolicy_stage_active_effectiveAt_expiresAt_idx" ON "AcquisitionStagePolicy"("stage","active","effectiveAt","expiresAt");
CREATE TABLE "AcquisitionFunnelBlocker" ("id" TEXT PRIMARY KEY,"funnelId" TEXT NOT NULL,"code" TEXT NOT NULL,"status" "FunnelBlockerStatus" NOT NULL DEFAULT 'OPEN',"explanation" TEXT NOT NULL,"sourceUrl" TEXT,"openedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3),"resolvedAt" TIMESTAMP(3),"resolvedBy" TEXT,"resolution" TEXT,CONSTRAINT "AcquisitionFunnelBlocker_funnelId_fkey" FOREIGN KEY ("funnelId") REFERENCES "AcquisitionFunnel"("id") ON DELETE RESTRICT,CONSTRAINT "AcquisitionFunnelBlocker_resolution_check" CHECK ("status" = 'OPEN' OR ("resolvedAt" IS NOT NULL AND "resolvedBy" IS NOT NULL AND "resolution" IS NOT NULL)));
CREATE INDEX "AcquisitionFunnelBlocker_funnelId_status_openedAt_idx" ON "AcquisitionFunnelBlocker"("funnelId","status","openedAt");
CREATE INDEX "AcquisitionFunnelBlocker_status_expiresAt_idx" ON "AcquisitionFunnelBlocker"("status","expiresAt");
CREATE TABLE "AcquisitionExpirationEvent" ("id" TEXT PRIMARY KEY,"funnelId" TEXT NOT NULL,"policyId" TEXT NOT NULL,"stageHistoryId" TEXT NOT NULL,"action" "AcquisitionExpiryAction" NOT NULL,"resultStage" "AcquisitionStage","reason" TEXT NOT NULL,"evidence" JSONB NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AcquisitionExpirationEvent_funnelId_fkey" FOREIGN KEY ("funnelId") REFERENCES "AcquisitionFunnel"("id") ON DELETE RESTRICT,CONSTRAINT "AcquisitionExpirationEvent_policyId_fkey" FOREIGN KEY ("policyId") REFERENCES "AcquisitionStagePolicy"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "AcquisitionExpirationEvent_funnelId_stageHistoryId_key" ON "AcquisitionExpirationEvent"("funnelId","stageHistoryId");
CREATE INDEX "AcquisitionExpirationEvent_action_occurredAt_idx" ON "AcquisitionExpirationEvent"("action","occurredAt");
